import { describe, expect, it, vi } from 'vitest';

import { resolveSemanticTokens } from './highlight-fallback';

/** 假时钟: `sleep` 只推进时间, 不需要真的等 */
function fakeClock() {
  let now = 0;
  return {
    now: () => now,
    sleep: async (ms: number) => {
      now += ms;
    },
    advance: (ms: number) => {
      now += ms;
    },
  };
}

describe('resolveSemanticTokens', () => {
  it('语言服务已经有答案时直接采用，不打扰本地兜底', async () => {
    const local = vi.fn(async () => [9]);
    const tokens = await resolveSemanticTokens({
      lsp: async () => [1, 2, 3],
      local,
      budgetMs: 1000,
      retryMs: 250,
    });

    expect(tokens).toEqual([1, 2, 3]);
    expect(local).not.toHaveBeenCalled();
  });

  it('空白答案不算数：在预算内重试，直到语言服务给出真结果', async () => {
    const clock = fakeClock();
    let calls = 0;
    const local = vi.fn(async () => [9]);
    const tokens = await resolveSemanticTokens({
      lsp: async () => (++calls < 3 ? null : [7, 8]),
      local,
      budgetMs: 1000,
      retryMs: 250,
      now: clock.now,
      sleep: clock.sleep,
    });

    expect(tokens).toEqual([7, 8]);
    expect(calls).toBe(3);
    expect(local).not.toHaveBeenCalled();
  });

  it('预算用完还是空：退回本地高亮', async () => {
    const clock = fakeClock();
    let calls = 0;
    const tokens = await resolveSemanticTokens({
      lsp: async () => {
        calls += 1;
        return null;
      },
      local: async () => [42],
      budgetMs: 1000,
      retryMs: 250,
      now: clock.now,
      sleep: clock.sleep,
    });

    expect(tokens).toEqual([42]);
    // 首次 + 4 次重试 (第 5 次询问前发现预算已耗尽)
    expect(calls).toBe(5);
  });

  it('语言服务报错时不再空等预算，直接走本地兜底', async () => {
    const clock = fakeClock();
    const tokens = await resolveSemanticTokens({
      lsp: async () => {
        throw new Error('LSP 连接已断开');
      },
      local: async () => [5],
      budgetMs: 10000,
      retryMs: 250,
      now: clock.now,
      sleep: clock.sleep,
    });

    expect(tokens).toEqual([5]);
    expect(clock.now()).toBe(0);
  });

  it('请求被取消后不再重试，也不返回会被丢弃的结果', async () => {
    const clock = fakeClock();
    const local = vi.fn(async () => [9]);
    let calls = 0;
    const tokens = await resolveSemanticTokens({
      lsp: async () => {
        calls += 1;
        return null;
      },
      local,
      budgetMs: 10000,
      retryMs: 250,
      isCancelled: () => true,
      now: clock.now,
      sleep: clock.sleep,
    });

    expect(tokens).toBeNull();
    expect(calls).toBe(1);
    expect(local).not.toHaveBeenCalled();
  });

  it('本地兜底也失败时返回 null (调用方按"没有结果"处理)', async () => {
    const tokens = await resolveSemanticTokens({
      lsp: async () => null,
      local: async () => {
        throw new Error('后端未就绪');
      },
      budgetMs: 0,
      retryMs: 250,
    });

    expect(tokens).toBeNull();
  });
});
